<script setup lang="ts">
import type { CaixaOperacional } from "~/types/padaria";
import { mensagemErro } from "~/utils/domain";
type Forma = "credito" | "debito" | "pix" | "voucher";
type Leitura = Record<Forma, number | null> & { documentoLegivel: boolean; numeroMaquininha: string | null; dataEmissao: string | null; acumulador: number | null; detalhes: Record<Forma, unknown[]>; camposDuvidosos: string[]; observacoes: string[] };
type Editavel = Omit<Leitura, Forma> & Record<Forma, string>;
const props = defineProps<{ caixa: CaixaOperacional }>();
const { apiUrl, apiGet, apiPost, apiPut } = useApi();
const campos = [{ chave: "credito", titulo: "Crédito" }, { chave: "debito", titulo: "Débito" }, { chave: "pix", titulo: "Pix" }, { chave: "voucher", titulo: "Voucher" }] as const;
const camera = useTemplateRef<HTMLInputElement>("camera"), galeria = useTemplateRef<HTMLInputElement>("galeria");
const etapa = ref<"manha" | "tarde">("manha"), anexoId = ref(""), base = ref<Editavel | null>(null), leitura = ref<Editavel>(nova(null));
const enviando = ref(false), salvando = ref(false), erro = ref(""), aviso = ref(""), salvo = ref(false);
const podeSalvar = computed(() => Boolean(anexoId.value) && campos.every(({ chave }) => valor(leitura.value[chave]) !== null));
function valor(v: unknown) { const n = Number(String(v).replace(",", ".")); return String(v).trim() && Number.isFinite(n) && n >= 0 ? n : null; }
function nova(v: unknown): Editavel { const d = v && typeof v === "object" ? v as Record<string, unknown> : {}; return { documentoLegivel: d.documentoLegivel === true, numeroMaquininha: typeof d.numeroMaquininha === "string" ? d.numeroMaquininha : null, dataEmissao: typeof d.dataEmissao === "string" ? d.dataEmissao : null, acumulador: typeof d.acumulador === "number" ? d.acumulador : null, credito: d.credito == null ? "" : String(d.credito), debito: d.debito == null ? "" : String(d.debito), pix: d.pix == null ? "" : String(d.pix), voucher: d.voucher == null ? "" : String(d.voucher), detalhes: { credito: [], debito: [], pix: [], voucher: [] }, camposDuvidosos: [], observacoes: [] }; }
function apiLeitura(): Leitura { return { ...leitura.value, credito: valor(leitura.value.credito), debito: valor(leitura.value.debito), pix: valor(leitura.value.pix), voucher: valor(leitura.value.voucher) }; }
function moeda(v: number | null) { return v === null ? "—" : v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }
function liquido(chave: Forma) { const atual = valor(leitura.value[chave]); const referencia = base.value ? valor(base.value[chave]) : 0; return atual === null || referencia === null ? null : atual - referencia; }
async function carregar() { if (!props.caixa.id) return; try { const r = await apiGet<{ etapaDia: "manha" | "tarde"; leituraReferencia: { leitura: unknown } | null; relatorio: { dadosRevisados: Record<string, unknown> } | null }>(`/api/caixa/${encodeURIComponent(props.caixa.id)}/relatorio-maquininha`); etapa.value = r.etapaDia; base.value = r.leituraReferencia?.leitura ? nova(r.leituraReferencia.leitura) : null; if (r.relatorio?.dadosRevisados?.anexoId) { anexoId.value = String(r.relatorio.dadosRevisados.anexoId); leitura.value = nova(r.relatorio.dadosRevisados.leituraAcumulada); salvo.value = true; } } catch (e) { erro.value = mensagemErro(e); } }
async function enviar(e: Event) { const input = e.target as HTMLInputElement; const arquivo = input.files?.[0]; input.value = ""; if (!arquivo || !props.caixa.id) return; enviando.value = true; try { const f = new FormData(); f.append("tipo", "comprovante_cartao"); f.append("arquivo", arquivo); const res = await fetch(`${apiUrl}/api/caixa/${encodeURIComponent(props.caixa.id)}/anexos`, { method: "POST", credentials: "include", body: f }); const json = await res.json() as { data?: { id: string }; detail?: string }; if (!res.ok || !json.data) throw new Error(json.detail || "Não foi possível anexar."); anexoId.value = json.data.id; const a = await apiPost<{ sugestao: Leitura }>(`/api/caixa/${encodeURIComponent(props.caixa.id)}/relatorio-maquininha/analisar`, { anexoId: json.data.id }); leitura.value = nova(a.sugestao); aviso.value = "A IA sugeriu os valores. Revise antes de salvar."; salvo.value = false; } catch (x) { erro.value = mensagemErro(x); } finally { enviando.value = false; } }
async function salvar() { if (!podeSalvar.value || !props.caixa.id) return; salvando.value = true; try { await apiPut(`/api/caixa/${encodeURIComponent(props.caixa.id)}/relatorio-maquininha`, { anexoId: anexoId.value, leituraAcumulada: apiLeitura() }); salvo.value = true; await carregar(); } catch (e) { erro.value = mensagemErro(e); } finally { salvando.value = false; } }
watch(() => props.caixa.id, () => void carregar(), { immediate: true });
</script>
<template><section class="maquininha"><header class="maquininha__cabecalho"><div><span>Etapa 3 · maquininha</span><h3>Relatório da {{ etapa === "manha" ? "manhã" : "tarde" }}</h3><p>{{ etapa === "manha" ? "Registre o acumulado deste turno." : "A manhã está vinculada; informe o acumulado e o sistema calcula somente a tarde." }}</p></div><v-chip :color="salvo ? 'success' : 'warning'" size="small">{{ salvo ? "Revisado" : "Pendente" }}</v-chip></header><v-alert v-if="base" type="info" density="compact" variant="tonal">Leitura da manhã vinculada ao mesmo PDV e máquina.</v-alert><section class="maquininha__foto"><div><strong>Comprovante do turno</strong><span>Envie por câmera ou galeria.</span></div><div class="maquininha__botoes"><v-btn prepend-icon="mdi-camera" @click="camera?.click()">Câmera</v-btn><v-btn prepend-icon="mdi-image" @click="galeria?.click()">Galeria</v-btn></div></section><input ref="camera" class="d-none" type="file" accept="image/*" capture="environment" @change="enviar"><input ref="galeria" class="d-none" type="file" accept="image/*,application/pdf" @change="enviar"><div class="maquininha__campos"><v-text-field v-for="c in campos" :key="c.chave" v-model="leitura[c.chave]" :label="c.titulo" prefix="R$" inputmode="decimal" /></div><section class="maquininha__liquidos"><h4>{{ etapa === "manha" ? "Total da manhã" : "Líquido da tarde" }}</h4><div><article v-for="c in campos" :key="c.chave"><span>{{ c.titulo }}</span><strong>{{ moeda(liquido(c.chave)) }}</strong><small>{{ etapa === "manha" ? "Acumulado" : "Acumulado menos manhã" }}</small></article></div></section><v-alert v-if="aviso" type="info" density="compact">{{ aviso }}</v-alert><v-alert v-if="erro" type="error" density="compact">{{ erro }}</v-alert><v-btn color="success" :loading="salvando" :disabled="!podeSalvar" @click="salvar">Salvar leitura da maquininha</v-btn></section></template>
<style src="./CaixaFechamentoMaquininha.css" scoped></style>
